settings.cardCss:
.water-status { display: grid; place-content: center; gap: 10px; height: 100%; text-align: center; font: 500 16px system-ui; color: #334155; }
.water-status strong { font-size: 26px; color: #334155; }
.water-status [data-status="NORMAL"] { color: #15803d; }
.water-status [data-status="WARNING"] { color: #a16207; }
.water-status [data-status="DANGER"] { color: #b91c1c; }

dataKeys.funcBody:
var value = prevValue + Math.random() * 100 - 50;
var multiplier = Math.pow(10, 2 || 0);
var value = Math.round(value * multiplier) / multiplier;
if (value < -1000) {
	value = -1000;
} else if (value > 1000) {
	value = 1000;
}
return value;
